import apiClient from './client'

export interface LicenseClaimRequest {
  order_id: string
  email: string
  install_id: string
  turnstile_token?: string | null
}

export interface LicenseClaimResponse {
  license_id: string
  download_url: string
  message: string
}

export async function claimLicense(
  payload: LicenseClaimRequest
): Promise<LicenseClaimResponse> {
  const response = await apiClient.post<LicenseClaimResponse>(
    '/v1/license/claim',
    payload
  )
  return response.data
}
