<template>
  <div class="claim-page">
    <el-card class="claim-card" shadow="always">
      <template #header>
        <div class="claim-header">
          <h1>{{ t('licenseClaim.title') }}</h1>
          <p>{{ t('licenseClaim.subtitle') }}</p>
        </div>
      </template>

      <template v-if="!result">
        <el-form
          :model="form"
          :rules="rules"
          ref="formRef"
          label-position="top"
          @keyup.enter="handleSubmit"
        >
          <el-form-item :label="t('licenseClaim.orderId')" prop="order_id">
            <el-input
              v-model="form.order_id"
              :placeholder="t('licenseClaim.orderIdPlaceholder')"
              size="large"
            />
          </el-form-item>
          <el-form-item :label="t('licenseClaim.email')" prop="email">
            <el-input
              v-model="form.email"
              :placeholder="t('licenseClaim.emailPlaceholder')"
              size="large"
            />
          </el-form-item>
          <el-form-item :label="t('licenseClaim.installId')" prop="install_id">
            <el-input
              v-model="form.install_id"
              :placeholder="t('licenseClaim.installIdPlaceholder')"
              size="large"
            />
          </el-form-item>
          <el-form-item>
            <el-button
              type="primary"
              size="large"
              :loading="loading"
              style="width: 100%"
              @click="handleSubmit"
            >
              {{ t('licenseClaim.submit') }}
            </el-button>
          </el-form-item>
        </el-form>

        <div v-if="errorMessage" class="claim-error">
          <el-alert :title="errorMessage" type="error" show-icon :closable="false" />
        </div>
      </template>

      <template v-else>
        <el-result icon="success" :title="t('licenseClaim.successTitle')">
          <template #sub-title>
            <p>{{ result.message }}</p>
            <p class="claim-hint">{{ t('licenseClaim.successHint') }}</p>
          </template>
          <template #extra>
            <el-button type="primary" size="large" @click="handleDownload">
              {{ t('licenseClaim.download') }}
            </el-button>
          </template>
        </el-result>
      </template>
    </el-card>
  </div>
</template>

<script setup lang="ts">
import { reactive, ref } from 'vue'
import type { FormInstance, FormRules } from 'element-plus'
import { ElMessage } from 'element-plus'
import { useI18n } from 'vue-i18n'
import { claimLicense, type LicenseClaimResponse } from '@/api/licenseClaim'
import { extractErrorMessage } from '@/utils/error'
import { getApiBaseUrl } from '@/api/client'

const { t } = useI18n()

const form = reactive({
  order_id: '',
  email: '',
  install_id: '',
})

const loading = ref(false)
const errorMessage = ref('')
const result = ref<LicenseClaimResponse | null>(null)
const formRef = ref<FormInstance>()

// 校验提示用函数延迟取值，保证切换语言后重新校验时提示跟着变
const rules: FormRules = {
  order_id: [
    {
      required: true,
      message: () => t('licenseClaim.orderIdRequired'),
      trigger: 'blur',
    },
    {
      pattern: /^[a-zA-Z0-9_-]{5,64}$/,
      message: () => t('licenseClaim.orderIdRequired'),
      trigger: 'blur',
    },
  ],
  email: [
    {
      required: true,
      message: () => t('licenseClaim.emailRequired'),
      trigger: 'blur',
    },
    {
      type: 'email',
      message: () => t('licenseClaim.emailInvalid'),
      trigger: 'blur',
    },
  ],
  install_id: [
    {
      required: true,
      message: () => t('licenseClaim.installIdRequired'),
      trigger: 'blur',
    },
    {
      pattern: /^ins_[a-zA-Z0-9]{16,64}$/,
      message: () => t('licenseClaim.installIdInvalid'),
      trigger: 'blur',
    },
  ],
}

async function handleSubmit() {
  if (!formRef.value) return
  const valid = await formRef.value.validate().catch(() => false)
  if (!valid) return

  loading.value = true
  errorMessage.value = ''
  try {
    result.value = await claimLicense({
      order_id: form.order_id.trim(),
      email: form.email.trim(),
      install_id: form.install_id.trim(),
    })
    ElMessage.success(result.value.message)
  } catch (error) {
    errorMessage.value = extractErrorMessage(error, t('licenseClaim.failed'))
  } finally {
    loading.value = false
  }
}

function handleDownload() {
  if (!result.value) return
  // download_url 为后端相对路径（含一次性 token），拼接 API base 后浏览器直接下载
  const base = getApiBaseUrl()
  window.location.href = `${base}${result.value.download_url}`
}
</script>

